/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METPrintMgmtReportFormatPopulatorAppSuite_Extension</c> populates the PrintMgmtReportFormat table used for print management 
/// with the documents.
/// </summary>
[ExtensionOf(classStr(PrintMgmtReportFormatPopulator))]
public final class METPrintMgmtReportFormatPopulatorAppSuite_Extension
{
    #ISOCountryRegionCodes
    #PrintMgmtSetup

}

Method.Source:
    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// adds documents
    /// </summary>
    protected void addDocuments()
    {
        //this.addStandard(PrintMgmtDocumentType::METCustActivityStatement);
        this.customAddSalesDocuments();

        next addDocuments();
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// Adds sales records to the PrintMgmtReportFormat table.
    /// </summary>
    private void customAddSalesDocuments()
    {
        //this.addStandard(PrintMgmtDocumentType::METCustActivityStatement, #NoCountryRegionId);
        //this.addOther(PrintMgmtDocumentType::METCustActivityStatement, ssrsReportStr(METCustActivityStatement, Report), ssrsReportStr(METCustActivityStatement, Report), #NoCountryRegionId);

        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METCustActivityStatement, ssrsReportStr(METCustActivityStatement, Report), ssrsReportStr(METCustActivityStatement, Report), #NoCountryRegionId, true);

        // MPJ_17952_PBMSReports1
        // Sales invoice
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, Liquor), ssrsReportStr(METSalesInvoice, Liquor), #NoCountryRegionId, true);
        // Purchase order
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Report), ssrsReportStr(METPurchPurchaseOrder, Report), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Food), ssrsReportStr(METPurchPurchaseOrder, Food), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Hardware), ssrsReportStr(METPurchPurchaseOrder, Hardware), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Liquor), ssrsReportStr(METPurchPurchaseOrder, Liquor), #NoCountryRegionId, true);


    }
